<script setup lang="ts">const shop=useShop();const form=reactive({name:'',email:'',topic:'Order question',message:''});function submit(){if(form.name.trim().length<2||!/^\S+@\S+\.\S+$/.test(form.email)||form.message.trim().length<10){shop.notify('Please complete every field and write at least 10 characters.','error');return}shop.notify('Message validated in demo mode. No email was sent.');form.name='';form.email='';form.topic='Order question';form.message=''} </script><template><div class="mx-auto w-full max-w-7xl px-4 sm:px-6 lg:px-8 py-12"><p class="text-xs font-bold uppercase tracking-[.2em] text-brand">We are here to help</p><h1 class="mt-2 text-4xl font-semibold tracking-tight sm:text-5xl">Say hello<span class="text-brand">.</span></h1><p class="mt-3 max-w-lg text-sm leading-6 text-gray-500">Questions, feedback, or just want to say hi? Send a demo message below.</p><div class="mt-9 grid gap-10 md:grid-cols-[.7fr_1.3fr]"><aside class="rounded-2xl bg-mist p-6"><h2 class="text-lg font-semibold">Get in touch</h2><p class="mt-3 text-sm leading-6 text-gray-500">This project is a frontend demonstration. Form submissions are not delivered to an inbox.</p><div class="mt-6 space-y-4 text-sm"><p><span class="block text-xs text-gray-500">Email concept</span>hello@vy-studio.example</p><p><span class="block text-xs text-gray-500">Location concept</span>Phnom Penh, Cambodia</p><p><span class="block text-xs text-gray-500">Typical reply</span>Within 1–2 business days (sample copy)</p></div></aside><form class="space-y-4" @submit.prevent="submit"><div class="grid gap-4 sm:grid-cols-2"><label class="text-xs font-semibold">Your name<input v-model="form.name" required class="mt-2 w-full rounded-xl border border-gray-200 px-4 py-3 text-sm"></label><label class="text-xs font-semibold">Email address<input v-model="form.email" type="email" required class="mt-2 w-full rounded-xl border border-gray-200 px-4 py-3 text-sm"></label></div><label class="block text-xs font-semibold">Topic<select v-model="form.topic" class="mt-2 w-full rounded-xl border border-gray-200 bg-white px-4 py-3 text-sm"><option>Order question</option><option>Product question</option><option>Shipping & returns</option><option>Feedback</option><option>Other</option></select></label><label class="block text-xs font-semibold">Message<textarea v-model="form.message" required minlength="10" rows="5" class="mt-2 w-full rounded-xl border border-gray-200 px-4 py-3 text-sm" placeholder="How can we help?"></textarea></label><button class="rounded-full bg-ink px-7 py-4 text-xs font-bold uppercase tracking-wider text-white hover:bg-brand">Send demo message ↗</button></form></div></div></template>
